// === Tab: mySketch ===
let particles = [] // 存储要生成的粒子（Particle对象）的列表/数组
let particleNum = 0 // 粒子总数，初始为0
let pg // 用于在画布上绘制（图形）的层/缓冲区（p5.Graphics 对象）
let font // 文本的字体
let tileSize = 0.5
let tileGap = 0.5

// 💡 NEW CONTROL VARIABLE: Adjust this value to change the particle animation speed.
// 0.1 = Very Slow, 1.0 = Original Speed, 2.0 = Double Speed
let animationSpeedMultiplier = 0.3 


// 初始化设置函数，只运行一次
function setup() {
  // --- UPDATED CANVAS SIZE LOGIC START ---
  let canvasHeight = window.innerHeight * 0.8;
  let canvasWidth = (1080 / 1920) * canvasHeight; // Maintains an aspect ratio of 1080:1920
  createCanvas(canvasWidth, canvasHeight);

  // 💡 Add this line to control the overall speed:
  frameRate(90); // Sets the animation to 30 frames per second (half speed)
  // --- UPDATED CANVAS SIZE LOGIC END ---
  background(255, 40) // **UPDATED: White background (255) with slight alpha (40)**

  pg = createGraphics(width, height) // 创建一个与主画布大小相同的图形缓冲区
  pg.background(255) // **UPDATED: White background (255) for the buffer**
  pg.textFont('Georgia')
  pg.textSize(24)
  pg.fill(0) // **UPDATED: Black text color (0)**
  pg.textAlign(LEFT, TOP)
  // The poem with newline characters
  const poem = "Dear Axin,\n \nToday we run\nwe chase for sun\nThe sun burns us\nwe live in fire\nAnd then reborn\nLife keeps on like this\nburn & reborn\nA new Axin, rise"
  pg.text(poem, 50, 50)

  // 遍历整个画布，以 tileGap 为步长进行采样
  for (let x = 0; x < width; x += tileGap ) {
    for (let y = 0; y < height; y += tileGap ) {
      // 检查当前 (x, y) 坐标在图形缓冲区 pg 上是否为文本
      // [0, 0, 0, 255] 是纯黑色（RGB=0, A=255）
      // **UPDATED LOGIC: Now checking if the pixel IS pure black (the text color)**
      let isTEXT = JSON.stringify(pg.get(x, y)) === JSON.stringify([0, 0, 0, 255])

      // 如果该位置是文本的一部分，就创建一个粒子
      if (isTEXT) {
        particles.push(new Particle(x, y, tileSize, '#000000'))
      }
    }
  }
}

// 绘制循环函数，每帧运行
function draw() {
  background(255, 40) // **UPDATED: White background (255) with slight alpha (40)**
  translate(0, 250); // 将整个坐标系向下平移 100 像素

  // 遍历所有粒子并调用它们的 display 方法进行绘制和更新
  for (let i = 0; i < particles.length; i++) {
    particles[i].display(i)
  }
}



// ===================================
// PARTICLE CLASS DEFINITION
// ===================================

class Particle {
  // 构造函数：在创建新粒子时被调用
  constructor(x, y, size, color) {
    this.x = x // 粒子的目标 X 坐标 
    this.y = y // 粒子的目标 Y 坐标 
    this.size = size // 粒子的大小
    this.color = color // 粒子的颜色

    // 粒子的当前位置 (未在 display/update 中使用，但已定义)
    this.pos = createVector(x, random(-30, -10)) 
    this.vel = createVector(0, 0.1) 
    this.acc = createVector(0, random(0, 1))
  }

  // 更新粒子的状态（当前为空，运动逻辑在 display 中实现）
  update() {
    const roundPosY = Math.round(this.pos.y/100) * 100 
  }

  // 绘制粒子
  display(ind) {
    // 基于帧数、索引和 animationSpeedMultiplier 计算运动
    // 💡 Speed is controlled here by multiplying frameCount by the global variable
    let n = ((frameCount * animationSpeedMultiplier) % 100) / 100 // n 在 0 到 1 之间循环
    let v = map(n, 0, 1, 0, TWO_PI)
    let motion = tan(v) * ind * 0.01 // 水平运动量

    let col = this.color 

    // 计算粒子的大小，使其周期性变化
    let size = sin((motion+0.5)) * this.size
    //let size = this.size

    fill(col) 
    noStroke() 

    // 绘制矩形粒子，X 坐标受 motion 影响
    rect(this.x + motion, this.y, size, size)
  }
}

